func (v *appendEntriesVerifier) PreAppendEntries(src, target string, req *raft.AppendEntriesRequest) (*raft.AppendEntriesResponse, error) {
	term := req.Term
	var ldr string
	if len(req.RPCHeader.Addr) > 0 {
		ldr = string(req.RPCHeader.Addr)
	} else {
		ldr = string(req.Leader)
	}

	if ldr != src {
		v.Lock()
		defer v.Unlock()
		v.errors = append(v.errors, fmt.Sprintf("Node %v sent an appendEntries request for term %d that said the leader was some other node %v", src, term, ldr))
	}
	v.RLock()
	tl, exists := v.leaderForTerm[term]
	v.RUnlock()
	if exists && tl != ldr {
		v.Lock()
		defer v.Unlock()
		v.errors = append(v.errors, fmt.Sprintf("Node %v sent an AppendEntries request for term %d, but node %v had already done some, multiple leaders for same term!", src, term, tl))
	}
	if !exists {
		v.Lock()
		tl, exists := v.leaderForTerm[term]
		if exists && tl != ldr {
			v.errors = append(v.errors, fmt.Sprintf("Node %v sent an AppendEntries request for term %d, but node %v had already done some, multiple leaders for same term!", src, term, tl))
		}
		if !exists {
			v.leaderForTerm[term] = ldr
		}
		v.Unlock()

	var req AppendEntriesRequest
	if err := dec.Decode(&req); err != nil {
		return err
	}
	rpc.Command = &req

	leaderAddr := req.RPCHeader.Addr
	if len(leaderAddr) == 0 {
		leaderAddr = req.Leader
	}

	// Check if this is a heartbeat
	if req.Term != 0 && leaderAddr != nil &&
		req.PrevLogEntry == 0 && req.PrevLogTerm == 0 &&
		len(req.Entries) == 0 && req.LeaderCommitIndex == 0 {
		isHeartbeat = true
	}

	if isHeartbeat {
		labels = []metrics.Label{{Name: "rpcType", Value: "Heartbeat"}}
	} else {
		labels = []metrics.Label{{Name: "rpcType", Value: "AppendEntries"}}
	}
case rpcRequestVote:

// Check for heartbeat fast-path
if isHeartbeat {
	n.heartbeatFnLock.Lock()
	fn := n.heartbeatFn
	n.heartbeatFnLock.Unlock()
	if fn != nil {
		fn(rpc)
		goto RESP
	}
}

// Setup a heartbeat fast-path to avoid head-of-line
// blocking where possible. It MUST be safe for this
// to be called concurrently with a blocking RPC.
trans.SetHeartbeatHandler(r.processHeartbeat)

// Update the commit index
if a.LeaderCommitIndex > 0 && a.LeaderCommitIndex > r.getCommitIndex() {
	start := time.Now()
	idx := min(a.LeaderCommitIndex, r.getLastIndex())
	r.setCommitIndex(idx)
	if r.configurations.latestIndex <= idx {
		r.setCommittedConfiguration(r.configurations.latest, r.configurations.latestIndex)
	}

func (r *Raft) persistVote(term uint64, candidate []byte) error {
	if err := r.stable.SetUint64(keyLastVoteTerm, term); err != nil {
		return err
	}
	if err := r.stable.Set(keyLastVoteCand, candidate); err != nil {
		return err
	}
	return nil
}

// StableStore is used to provide stable storage
// of key configurations to ensure safety.
type StableStore interface {
	Set(key []byte, val []byte) error

	// Get returns the value for key, or an empty byte slice if key was not found.
	Get(key []byte) ([]byte, error)

	SetUint64(key []byte, val uint64) error

	// GetUint64 returns the uint64 value for key, or 0 if key was not found.
	GetUint64(key []byte) (uint64, error)
}

// Check if we've voted in this election before
if lastVoteTerm == req.Term && lastVoteCandBytes != nil {
	r.logger.Info("duplicate requestVote for same term", "term", req.Term)
	if bytes.Equal(lastVoteCandBytes, candidateBytes) {
		r.logger.Warn("duplicate requestVote from", "candidate", candidate)
		resp.Granted = true
	}
	return
}

// leadershipTransfer is doing the heavy lifting for the leadership transfer.
func (r *Raft) leadershipTransfer(id ServerID, address ServerAddress, repl *followerReplication, stopCh chan struct{}, doneCh chan error) {
	// make sure we are not already stopped
	select {
	case <-stopCh:
		doneCh <- nil
		return
	default:
	}

	for atomic.LoadUint64(&repl.nextIndex) <= r.getLastIndex() {
		err := &deferError{}
		err.init()
		repl.triggerDeferErrorCh <- err
		select {
		case err := <-err.errCh:
			if err != nil {
				doneCh <- err
				return
			}
		case <-stopCh:
			doneCh <- nil
			return
		}

// Make the RPC call
start = time.Now()
if err := r.trans.AppendEntries(peer.ID, peer.Address, &req, &resp); err != nil {
	r.logger.Error("failed to appendEntries to", "peer", peer, "error", err)
	s.failures++
	return
}

